 'demo.global.selected_schiil':["Schiil at this position","이 위치의 Schiil","Schiil à cet endroit","Schiil op deze positie"],
 'demo.global.sample_pixel':["Sample pixel","샘플 픽셀","Pixel d’exemple","Voorbeeldpixel"],
 'demo.global.empty_pixel':["This position is empty","이 위치는 아직 비어 있습니다","Cet endroit est vide","Deze positie is leeg"],
